  const campo = document.getElementById("titulo");
  const titulo = campo.value.trim();
  if (!titulo) return;
  agir(() => chamar("/api/itens", { method: "POST", body: JSON.stringify({ titulo }) })).then(() => { campo.value = ""; });
});

agir(() => Promise.resolve());

